// A simple spec‐level predicate saying that a mathematical integer x is a power of two.
#[verus::spec]
fn is_power_of_two(x: int) -> bool {
    x > 0 && (x & (x - 1)) == 0
}

/// Compute the largest power of two ≤ n, for n ≥ 1.
